<script setup lang="ts">
import { Check, ChevronLeft, ChevronRight, Clipboard, KeyRound, Link2, LockKeyhole, Search, ShieldCheck, UserRoundCheck, UserRoundX, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const result = ref<any>({ items: [], total: 0, page: 1, pages: 1, totals: { all: 0, staff: 0, b2c: 0, b2b: 0, pendingChanges: 0 } });
const requests = ref<any[]>([]);
const type = ref<'ALL'|'STAFF'|'B2C'|'B2B'>('ALL');
const search = ref('');
const page = ref(1);
const busy = ref(false);
const selected = ref<any>(null);
const notice = ref('');
const error = ref('');
const resetInfo = ref<any>(null);
const temporary = reactive({ currentAdminPassword: '', temporaryPassword: '' });
const edit = reactive({ firstName: '', lastName: '', email: '', phone: '' });
let searchTimer: ReturnType<typeof setTimeout> | undefined;
const headers = computed(() => ({ Authorization: `Bearer ${token.value}` }));
const roleLabels: Record<string,string> = { ADMIN:'Администратор платформы',CONTENT_MANAGER:'Контент-менеджер',MANAGER_B2B:'Менеджер B2B',MANAGER_SALES:'Менеджер продаж',MARKETPLACE_MANAGER:'Менеджер маркетплейсов',SUPERVISOR:'Руководитель направления',EXECUTIVE:'Руководитель компании',IT_SUPPORT:'IT-поддержка',CURATOR:'Куратор',WAREHOUSE:'Сотрудник склада',CUSTOMER_B2C:'Клиент B2C',CUSTOMER_B2B:'Партнёр B2B' };
const tabs = computed(() => [
  { id:'ALL', label:'Все', count:result.value.totals.all }, { id:'STAFF',label:'Сотрудники',count:result.value.totals.staff },
  { id:'B2C',label:'Клиенты B2C',count:result.value.totals.b2c }, { id:'B2B',label:'Партнёры B2B',count:result.value.totals.b2b },
]);

async function load() {
  busy.value = true; error.value = '';
  try {
    result.value = await $fetch('/system-settings/accounts', { baseURL: config.public.apiBase, headers: headers.value, query: { type:type.value, search:search.value || undefined, page:page.value, limit:30 } });
    requests.value = await $fetch<any[]>('/system-settings/profile-change-requests', { baseURL: config.public.apiBase, headers: headers.value });
  } catch (exception:any) { error.value = messageOf(exception); }
  finally { busy.value = false; }
}
function selectType(value:any){ type.value=value; page.value=1; load(); }
function openAccount(item:any){ selected.value=item; resetInfo.value=null; error.value=''; Object.assign(edit,{firstName:item.firstName||'',lastName:item.lastName||'',email:item.email||'',phone:item.phone||''}); Object.assign(temporary,{currentAdminPassword:'',temporaryPassword:''}); }
async function updateAccount(change:any = edit){
  if(!selected.value) return;
  await act(async()=>{ await $fetch(`/system-settings/accounts/${selected.value.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:headers.value,body:change}); await load(); selected.value={...selected.value,...change}; showNotice('Учётная запись обновлена'); });
}
async function createReset(){
  await act(async()=>{ resetInfo.value=await $fetch(`/system-settings/accounts/${selected.value.id}/password-reset`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value}); showNotice('Одноразовая ссылка создана на 1 час'); });
}
async function setTemporary(){
  await act(async()=>{ await $fetch(`/system-settings/accounts/${selected.value.id}/temporary-password`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:temporary}); temporary.currentAdminPassword='';temporary.temporaryPassword='';await load();showNotice('Временный пароль установлен, все сессии завершены'); });
}
async function moveToTrash(item:any){
  selected.value=item;
  await act(async()=>{await $fetch(`/data-lifecycle/USER/${item.id}/trash`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{reason:'Удалено администратором из реестра учётных записей'}});selected.value=null;await load();showNotice('Учётная запись перемещена в корзину')});
}
async function review(request:any,status:'APPROVED'|'REJECTED'){
  await act(async()=>{ await $fetch(`/system-settings/profile-change-requests/${request.id}/review`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{status}});await load();showNotice(status==='APPROVED'?'Изменения подтверждены':'Запрос отклонён'); });
}
function accountMenu(event:MouseEvent,item:any){const name=[item.firstName,item.lastName].filter(Boolean).join(' ')||item.email;openContextMenu(event,name,[{label:'Открыть карточку',icon:'open',action:()=>openAccount(item)},{label:'Копировать email',icon:'copy',action:()=>copyText(item.email,'Email скопирован')},{label:item.isActive?'Заблокировать':'Разблокировать',icon:'block',separator:true,danger:item.isActive,disabled:item.id===user.value?.id,confirm:item.isActive?`Заблокировать «${name}» и завершить все сессии?`:undefined,action:()=>{selected.value=item;updateAccount({isActive:!item.isActive})}},{label:'Переместить в корзину',icon:'archive',danger:true,disabled:item.id===user.value?.id,confirm:`Переместить учётную запись «${name}» в корзину? Доступ будет немедленно закрыт.`,action:()=>moveToTrash(item)}],roleLabels[item.role]);}
async function act(callback:()=>Promise<void>){busy.value=true;error.value='';try{await callback()}catch(exception:any){error.value=messageOf(exception)}finally{busy.value=false}}
function messageOf(exception:any){return exception?.data?.message||exception?.message||'Не удалось выполнить действие'}
function showNotice(value:string){notice.value=value;setTimeout(()=>notice.value='',2600)}
function personName(item:any){return [item.firstName,item.lastName].filter(Boolean).join(' ')||'Без имени'}
watch(search,()=>{if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;load()},350)});
onMounted(load);
</script>

<template>
  <section data-v-ui-0dbb46e8d1df class="accounts-panel crm-surface">
    <div data-v-ui-0dbb46e8d1df class="account-summary"><button class="crm-button" data-v-ui-0dbb46e8d1df v-for="tab in tabs" :key="tab.id" :class="{active:type===tab.id}" @click="selectType(tab.id)"><span data-v-ui-0dbb46e8d1df>{{tab.label}}</span><strong data-v-ui-0dbb46e8d1df>{{tab.count}}</strong></button></div>
    <div data-v-ui-0dbb46e8d1df v-if="requests.length" class="requests"><header data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df><p data-v-ui-0dbb46e8d1df>ТРЕБУЮТ РЕШЕНИЯ</p><h2 data-v-ui-0dbb46e8d1df>Запросы на изменение данных</h2></div><b data-v-ui-0dbb46e8d1df>{{requests.length}}</b></header><article data-v-ui-0dbb46e8d1df v-for="request in requests" :key="request.id"><div data-v-ui-0dbb46e8d1df class="request-person"><i data-v-ui-0dbb46e8d1df>{{(request.user.firstName||request.user.email).slice(0,1).toUpperCase()}}</i><span data-v-ui-0dbb46e8d1df><strong data-v-ui-0dbb46e8d1df>{{personName(request.user)}}</strong><small data-v-ui-0dbb46e8d1df>{{request.user.email}} · {{new Date(request.createdAt).toLocaleString('ru-RU')}}</small></span></div><div data-v-ui-0dbb46e8d1df class="changes"><span data-v-ui-0dbb46e8d1df v-if="request.requestedData.firstName">Имя: <b data-v-ui-0dbb46e8d1df>{{request.requestedData.firstName}}</b></span><span data-v-ui-0dbb46e8d1df v-if="request.requestedData.lastName">Фамилия: <b data-v-ui-0dbb46e8d1df>{{request.requestedData.lastName}}</b></span><span data-v-ui-0dbb46e8d1df v-if="request.requestedData.phone">Телефон: <b data-v-ui-0dbb46e8d1df>{{request.requestedData.phone}}</b></span></div><div data-v-ui-0dbb46e8d1df class="request-actions"><button class="crm-button" data-v-ui-0dbb46e8d1df title="Подтвердить" @click="review(request,'APPROVED')"><Check data-v-ui-0dbb46e8d1df :size="16"/></button><button class="crm-button" data-v-ui-0dbb46e8d1df title="Отклонить" @click="review(request,'REJECTED')"><X data-v-ui-0dbb46e8d1df :size="16"/></button></div></article></div>
    <div data-v-ui-0dbb46e8d1df class="accounts-card">
      <header data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df><p data-v-ui-0dbb46e8d1df>ЕДИНЫЙ РЕЕСТР</p><h2 data-v-ui-0dbb46e8d1df>Учётные записи платформы</h2><span data-v-ui-0dbb46e8d1df>Сотрудники, покупатели сайта и партнёры B2B в одном защищённом контуре</span></div><label class="crm-input-group" data-v-ui-0dbb46e8d1df><Search data-v-ui-0dbb46e8d1df :size="16"/><input class="crm-input" data-v-ui-0dbb46e8d1df v-model.trim="search" placeholder="Имя, email, телефон или компания"/></label></header>
      <div data-v-ui-0dbb46e8d1df class="account-table"><div data-v-ui-0dbb46e8d1df class="account-row head crm-table-head"><span data-v-ui-0dbb46e8d1df>Пользователь</span><span data-v-ui-0dbb46e8d1df>Тип</span><span data-v-ui-0dbb46e8d1df>Организация</span><span data-v-ui-0dbb46e8d1df>Сессии</span><span data-v-ui-0dbb46e8d1df>Состояние</span></div><button data-v-ui-0dbb46e8d1df v-for="item in result.items" :key="item.id" class="account-row crm-button crm-table-row crm-card-action" @click="openAccount(item)" @contextmenu.prevent="accountMenu($event,item)"><span data-v-ui-0dbb46e8d1df class="account-person"><i class="crm-avatar" data-v-ui-0dbb46e8d1df><img data-v-ui-0dbb46e8d1df v-if="item.avatarUrl" :src="new URL(item.avatarUrl,config.public.apiBase).toString()" alt=""/><template v-else>{{(item.firstName||item.email).slice(0,1).toUpperCase()}}</template></i><span data-v-ui-0dbb46e8d1df><strong data-v-ui-0dbb46e8d1df>{{personName(item)}}</strong><small data-v-ui-0dbb46e8d1df>{{item.email}}<template v-if="item.phone"> · {{item.phone}}</template></small></span></span><span data-v-ui-0dbb46e8d1df><em class="crm-badge" data-v-ui-0dbb46e8d1df :class="item.accountType.toLowerCase()">{{item.accountType==='STAFF'?'Сотрудник':item.accountType==='B2B'?'B2B':'B2C'}}</em><small data-v-ui-0dbb46e8d1df>{{roleLabels[item.role]}}</small></span><span data-v-ui-0dbb46e8d1df>{{item.b2bProfile?.companyName||item.organizationMemberships?.[0]?.organization?.name||'—'}}</span><span data-v-ui-0dbb46e8d1df>{{item._count.sessions}}</span><span data-v-ui-0dbb46e8d1df class="crm-badge" :data-status="item.isActive ? 'ACTIVE' : 'SUSPENDED'" :class="item.isActive?'state-active':'state-blocked'">{{item.isActive?'Активна':'Заблокирована'}}</span></button><div data-v-ui-0dbb46e8d1df v-if="!result.items.length&&!busy" class="empty"><Users data-v-ui-0dbb46e8d1df :size="26"/><span data-v-ui-0dbb46e8d1df>Учётные записи не найдены</span></div></div>
      <footer data-v-ui-0dbb46e8d1df><span data-v-ui-0dbb46e8d1df>Показано {{result.items.length}} из {{result.total}}</span><div data-v-ui-0dbb46e8d1df><button class="crm-button" data-v-ui-0dbb46e8d1df :disabled="page<=1" @click="page--;load()"><ChevronLeft data-v-ui-0dbb46e8d1df :size="16"/></button><b data-v-ui-0dbb46e8d1df>{{page}} / {{result.pages}}</b><button class="crm-button" data-v-ui-0dbb46e8d1df :disabled="page>=result.pages" @click="page++;load()"><ChevronRight data-v-ui-0dbb46e8d1df :size="16"/></button></div></footer>
    </div>
    <Teleport to="body"><div data-v-ui-0dbb46e8d1df v-if="selected" class="account-backdrop admin-dialog-backdrop" @mousedown.self="selected=null"><aside data-v-ui-0dbb46e8d1df class="account-drawer admin-dialog admin-dialog--drawer"><header data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df><p data-v-ui-0dbb46e8d1df>УЧЁТНАЯ ЗАПИСЬ</p><h2 data-v-ui-0dbb46e8d1df>{{personName(selected)}}</h2><span data-v-ui-0dbb46e8d1df>{{roleLabels[selected.role]}}</span></div><button class="crm-button" data-v-ui-0dbb46e8d1df @click="selected=null"><X data-v-ui-0dbb46e8d1df :size="19"/></button></header><div data-v-ui-0dbb46e8d1df class="drawer-body admin-dialog-body"><section data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df class="section-title"><div data-v-ui-0dbb46e8d1df><h3 data-v-ui-0dbb46e8d1df>Контактные данные</h3><p data-v-ui-0dbb46e8d1df>Изменения применяются сразу и попадают в журнал аудита.</p></div><Users data-v-ui-0dbb46e8d1df :size="18"/></div><div data-v-ui-0dbb46e8d1df class="fields"><label data-v-ui-0dbb46e8d1df><span data-v-ui-0dbb46e8d1df>Имя</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model.trim="edit.firstName"/></label><label data-v-ui-0dbb46e8d1df><span data-v-ui-0dbb46e8d1df>Фамилия</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model.trim="edit.lastName"/></label><label data-v-ui-0dbb46e8d1df class="wide"><span data-v-ui-0dbb46e8d1df>Email</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model.trim="edit.email" type="email"/></label><label data-v-ui-0dbb46e8d1df class="wide"><span data-v-ui-0dbb46e8d1df>Телефон</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model.trim="edit.phone"/></label></div><button data-v-ui-0dbb46e8d1df class="primary crm-button crm-button--primary" @click="updateAccount()">Сохранить данные</button></section><section data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df class="section-title"><div data-v-ui-0dbb46e8d1df><h3 data-v-ui-0dbb46e8d1df>Доступ</h3><p data-v-ui-0dbb46e8d1df>Блокировка немедленно завершает активные сессии.</p></div><ShieldCheck data-v-ui-0dbb46e8d1df :size="18"/></div><div data-v-ui-0dbb46e8d1df class="access-state"><span data-v-ui-0dbb46e8d1df><strong data-v-ui-0dbb46e8d1df>{{selected.isActive?'Доступ разрешён':'Доступ заблокирован'}}</strong><small data-v-ui-0dbb46e8d1df>Активных сессий: {{selected._count.sessions}}</small></span><button class="crm-button" data-v-ui-0dbb46e8d1df :disabled="selected.id===user?.id" @click="updateAccount({isActive:!selected.isActive})"><UserRoundX data-v-ui-0dbb46e8d1df v-if="selected.isActive" :size="16"/><UserRoundCheck data-v-ui-0dbb46e8d1df v-else :size="16"/>{{selected.isActive?'Заблокировать':'Разблокировать'}}</button></div></section><section data-v-ui-0dbb46e8d1df><div data-v-ui-0dbb46e8d1df class="section-title"><div data-v-ui-0dbb46e8d1df><h3 data-v-ui-0dbb46e8d1df>Восстановление пароля</h3><p data-v-ui-0dbb46e8d1df>Пароли никогда не отображаются и не отправляются в открытом виде.</p></div><KeyRound data-v-ui-0dbb46e8d1df :size="18"/></div><button data-v-ui-0dbb46e8d1df class="secondary full crm-button" @click="createReset"><Link2 data-v-ui-0dbb46e8d1df :size="16"/>Создать одноразовую ссылку</button><div data-v-ui-0dbb46e8d1df v-if="resetInfo" class="reset-link"><input class="crm-input" data-v-ui-0dbb46e8d1df :value="resetInfo.resetUrl" readonly/><button class="crm-button" data-v-ui-0dbb46e8d1df title="Копировать" @click="copyText(resetInfo.resetUrl,'Ссылка скопирована')"><Clipboard data-v-ui-0dbb46e8d1df :size="16"/></button><small data-v-ui-0dbb46e8d1df>Действует до {{new Date(resetInfo.expiresAt).toLocaleString('ru-RU')}}. Отправка письмом появится после подключения почтового провайдера.</small></div><div data-v-ui-0dbb46e8d1df class="temp-password"><h4 data-v-ui-0dbb46e8d1df>Или установить временный пароль</h4><label data-v-ui-0dbb46e8d1df><span data-v-ui-0dbb46e8d1df>Ваш пароль администратора</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model="temporary.currentAdminPassword" type="password"/></label><label data-v-ui-0dbb46e8d1df><span data-v-ui-0dbb46e8d1df>Временный пароль для пользователя</span><input class="crm-input" data-v-ui-0dbb46e8d1df v-model="temporary.temporaryPassword" type="password" placeholder="Не менее 10 символов"/></label><button data-v-ui-0dbb46e8d1df class="secondary full crm-button" :disabled="!temporary.currentAdminPassword||!temporary.temporaryPassword" @click="setTemporary"><LockKeyhole data-v-ui-0dbb46e8d1df :size="16"/>Установить и завершить сессии</button></div></section></div></aside></div></Teleport>
    <p data-v-ui-0dbb46e8d1df v-if="error" class="account-error">{{error}}</p><p data-v-ui-0dbb46e8d1df v-if="notice" class="account-notice"><Check data-v-ui-0dbb46e8d1df :size="15"/>{{notice}}</p>
  </section>
</template>
